// about/index.html is GENERATED by scripts/about-build.mjs from the game's own data (units, strings, zones, tiers),
// so the committed page must match a fresh build, carry the 12 languages, link the game and the legal pages, and
// pull nothing from a third party except the two Google Fonts the game already uses.
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { readFileSync, existsSync } from 'node:fs';
import { buildAbout, LANGS } from '../scripts/about-build.mjs';
import { loadI18N } from './helpers/i18n.js';

const root = new URL('../', import.meta.url);
const read = p => readFileSync(new URL(p, root), 'utf8');

test('about/index.html exists and matches a fresh build (run: node scripts/about-build.mjs)', () => {
  assert.ok(existsSync(new URL('about/index.html', root)), 'about/index.html missing');
  assert.equal(read('about/index.html'), buildAbout(), 'about/index.html is stale: run node scripts/about-build.mjs');
});

test('the page names the game, links back to it and to the legal pages, and carries Open Graph tags', () => {
  const h = read('about/index.html');
  assert.match(h, /^<!doctype html>/i);
  assert.match(h, /<meta name="viewport"/);
  assert.match(h, /<meta property="og:url" content="https:\/\/swishby\.com\/about\/">/);
  assert.match(h, /<meta property="og:image" content="https:\/\/swishby\.com\/og-swishby\.png">/);
  assert.match(h, /href="\.\.\/"/, 'links to the game at the site root');
  assert.match(h, /href="\.\.\/terms\.html"/); assert.match(h, /href="\.\.\/privacy\.html"/);
  assert.ok(h.includes('미니멀코리아'), 'operator in the footer');
});

test('every language of the game is on the page, with its own words for the page copy', () => {
  const h = read('about/index.html');
  const m = h.match(/<script id="about-data" type="application\/json">([\s\S]*?)<\/script>/);
  assert.ok(m, 'embedded data block');
  const d = JSON.parse(m[1]);
  assert.deepEqual(Object.keys(d.langs).sort(), [...LANGS].sort());
  for (const l of LANGS){
    for (const k of ['sub', 'h_run', 'h_modes', 'h_units', 'h_season', 'next_season', 'tag', 'c1', 'c5', 'pt_demigod', 'r_monarch']) {
      assert.ok(typeof d.langs[l][k] === 'string' && d.langs[l][k].length > 1, `${l}.${k}`);
    }
    if (l !== 'en') assert.notEqual(d.langs[l].h_units, d.langs.en.h_units, l + ' heading still English');
  }
  assert.equal(d.units.length, 24, '24 visible units (celestial released 2027-01-01)');
  assert.ok(d.units.every(u => u.stats.length === 4 && u.name && u.id), 'each unit has a name, id and 4 stats');
  assert.ok(!d.units.some(u => ['aurora', 'tempest', 'pleiad'].includes(u.id)), 'unreleased units stay hidden');
  assert.equal(d.tiers.length, 7);
});

test('the game links the about page from its help card, in every language', () => {
  const h = read('index.html');
  const help = h.slice(h.indexOf('class="card helpcard"'), h.indexOf('id="vsScr"'));
  assert.match(help, /href="about\/"[^>]*data-i18n="legalAbout"/);
  const I = loadI18N();
  for (const l of LANGS) assert.ok(I[l].legalAbout && (l === 'en' || I[l].legalAbout !== I.en.legalAbout), l + '.legalAbout');
});

test('no third-party request beyond the two Google Fonts the game already uses', () => {
  const h = read('about/index.html');
  const hosts = [...h.matchAll(/https?:\/\/([a-z0-9.-]+)/gi)].map(x => x[1].toLowerCase());
  const bad = hosts.filter(x => !['fonts.googleapis.com', 'fonts.gstatic.com', 'swishby.com'].includes(x));
  assert.deepEqual([...new Set(bad)], []);
  assert.ok(!/supabase/i.test(h), 'the about page talks to no backend');
});

test('motion and layout basics: reduced motion honoured, no horizontal overflow rules', () => {
  const h = read('about/index.html');
  assert.match(h, /prefers-reduced-motion/);
  assert.match(h, /overflow-x:\s*hidden/);
  assert.match(h, /<canvas id="attract"/, 'the hero plays the game to itself');
});
